    "code": "# The pool of application servers. Nginx rotates through them for each request.\nupstream api {\n    server host.docker.internal:3001;\n    server host.docker.internal:3002;\n    keepalive 32;\n}\n\nserver {\n    listen 80;\n    server_name _;\n\n    # Reject oversized bodies here, before they reach the application.\n    client_max_body_size 1m;\n\n    # Static files are served directly, without touching the application.\n    location /static/ {\n        root /var/www;\n        expires 7d;\n    }\n\n    location / {\n        proxy_pass http://api;\n\n        # Reuse upstream connections instead of opening one per request.\n        proxy_http_version 1.1;\n        proxy_set_header Connection \"\";\n\n        # Tell the application who really called. Clients can send these headers\n        # themselves, so an edge proxy must overwrite them, never append to them.\n        # Otherwise a forged address reaches the app and defeats IP rate limits.\n        proxy_set_header Host $host;\n        proxy_set_header X-Real-IP $remote_addr;\n        proxy_set_header X-Forwarded-For $remote_addr;\n        proxy_set_header X-Forwarded-Proto $scheme;\n\n        # Give up on a slow server rather than holding the connection open.\n        proxy_connect_timeout 2s;\n        proxy_read_timeout 10s;\n    }\n}"
